-- branches from lossless bronze, typed against platform/contracts/sources/branches.yml
-- (contract 2dfb3f6d17d6). Generated by scripts/generate_silver_from_contracts.py: do not edit, change the contract and regenerate.
-- '' and absent fields become NULL; a value that does not cast becomes NULL and is listed in _dq_issues
-- as '<column>:<code>' (see audit.dq_cell_findings). Every bronze record is kept, flagged or not.
-- Approved corrections (dq_corrections_active, four-eyes) are overlaid on the text before typing; _dq_issues
-- stays computed on the original text (what the source sent) and _corrected_columns lists what the overlay changed.
with c as (
    select source_file, record_no,
           map_from_entries(list(struct_pack(k := column_name, v := new_value) ORDER BY column_name)) AS m
    from {{ ref('dq_corrections_active') }}
    where zone = 'bronze' and table_name = 'branches'
    group by all
),
o as (
    select r.*, list_filter([
        CASE WHEN r._parse_status <> 'ok' THEN '*:G' END,
        CASE WHEN coalesce(r."branch_id", '') = '' THEN 'branch_id:N' END,
        CASE WHEN r."branch_id" <> '' AND NOT regexp_full_match(r."branch_id", 'SUC-[0-9A-Z]{8}') THEN 'branch_id:K' END,
        CASE WHEN coalesce(r."branch_code", '') = '' THEN 'branch_code:N' END,
        CASE WHEN coalesce(r."branch_name", '') = '' THEN 'branch_name:N' END,
        CASE WHEN coalesce(r."branch_type", '') = '' THEN 'branch_type:N' END,
        CASE WHEN r."branch_type" <> '' AND r."branch_type" NOT IN ('Corporate', 'Express', 'Main', 'Premium') THEN 'branch_type:V1' END,
        CASE WHEN coalesce(r."address", '') = '' THEN 'address:N' END,
        CASE WHEN coalesce(r."city", '') = '' THEN 'city:N' END,
        CASE WHEN r."city" <> '' AND r."city" NOT IN ('Barranquilla', 'Bogotá', 'Buenos Aires', 'Cali', 'Cartagena', 'Ciudad de México', 'Córdoba', 'Guadalajara', 'La Plata', 'Medellín', 'Mendoza', 'Monterrey', 'Puebla', 'Querétaro', 'Rosario', 'Tijuana') THEN 'city:V1' END,
        CASE WHEN coalesce(r."state", '') = '' THEN 'state:N' END,
        CASE WHEN r."state" <> '' AND r."state" NOT IN ('Antioquia', 'Atlántico', 'Baja California', 'Bolívar', 'Buenos Aires', 'Ciudad Autónoma de Buenos Aires', 'Ciudad de México', 'Cundinamarca', 'Córdoba', 'Jalisco', 'Mendoza', 'Nuevo León', 'Puebla', 'Querétaro', 'Santa Fe', 'Valle del Cauca') THEN 'state:V1' END,
        CASE WHEN coalesce(r."country", '') = '' THEN 'country:N' END,
        CASE WHEN r."country" <> '' AND r."country" NOT IN ('Argentina', 'Colombia', 'México') THEN 'country:V1' END,
        CASE WHEN coalesce(r."postal_code", '') = '' THEN 'postal_code:N' END,
        CASE WHEN coalesce(r."geographic_zone", '') = '' THEN 'geographic_zone:N' END,
        CASE WHEN r."geographic_zone" <> '' AND r."geographic_zone" NOT IN ('Urbana') THEN 'geographic_zone:V1' END,
        CASE WHEN coalesce(r."phone", '') = '' THEN 'phone:N' END,
        CASE WHEN coalesce(r."email", '') = '' THEN 'email:N' END,
        CASE WHEN coalesce(r."opening_time", '') = '' THEN 'opening_time:N' END,
        CASE WHEN r."opening_time" <> '' AND try_cast(r."opening_time" AS TIME) IS NULL THEN 'opening_time:T' END,
        CASE WHEN r."opening_time" <> '' AND NOT regexp_full_match(r."opening_time", '(?:[0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?)') AND try_cast(r."opening_time" AS TIME) IS NOT NULL THEN 'opening_time:F' END,
        CASE WHEN coalesce(r."closing_time", '') = '' THEN 'closing_time:N' END,
        CASE WHEN r."closing_time" <> '' AND try_cast(r."closing_time" AS TIME) IS NULL THEN 'closing_time:T' END,
        CASE WHEN r."closing_time" <> '' AND NOT regexp_full_match(r."closing_time", '(?:[0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]+)?)?)') AND try_cast(r."closing_time" AS TIME) IS NOT NULL THEN 'closing_time:F' END,
        CASE WHEN coalesce(r."has_atms", '') = '' THEN 'has_atms:N' END,
        CASE WHEN r."has_atms" <> '' AND try_cast(r."has_atms" AS BOOLEAN) IS NULL THEN 'has_atms:T' END,
        CASE WHEN r."has_atms" <> '' AND NOT regexp_full_match(r."has_atms", '(?i:(true|false))') AND try_cast(r."has_atms" AS BOOLEAN) IS NOT NULL THEN 'has_atms:F' END,
        CASE WHEN coalesce(r."atm_count", '') = '' THEN 'atm_count:N' END,
        CASE WHEN r."atm_count" <> '' AND try_cast(r."atm_count" AS BIGINT) IS NULL THEN 'atm_count:T' END,
        CASE WHEN r."atm_count" <> '' AND NOT regexp_full_match(r."atm_count", '(?:[+-]?[0-9]+)') AND try_cast(r."atm_count" AS BIGINT) IS NOT NULL THEN 'atm_count:F' END,
        CASE WHEN coalesce(r."has_teller_windows", '') = '' THEN 'has_teller_windows:N' END,
        CASE WHEN r."has_teller_windows" <> '' AND try_cast(r."has_teller_windows" AS BOOLEAN) IS NULL THEN 'has_teller_windows:T' END,
        CASE WHEN r."has_teller_windows" <> '' AND NOT regexp_full_match(r."has_teller_windows", '(?i:(true|false))') AND try_cast(r."has_teller_windows" AS BOOLEAN) IS NOT NULL THEN 'has_teller_windows:F' END,
        CASE WHEN coalesce(r."teller_window_count", '') = '' THEN 'teller_window_count:N' END,
        CASE WHEN r."teller_window_count" <> '' AND try_cast(r."teller_window_count" AS BIGINT) IS NULL THEN 'teller_window_count:T' END,
        CASE WHEN r."teller_window_count" <> '' AND NOT regexp_full_match(r."teller_window_count", '(?:[+-]?[0-9]+)') AND try_cast(r."teller_window_count" AS BIGINT) IS NOT NULL THEN 'teller_window_count:F' END,
        CASE WHEN coalesce(r."latitude", '') = '' THEN 'latitude:N' END,
        CASE WHEN r."latitude" <> '' AND try_cast(r."latitude" AS DOUBLE) IS NULL THEN 'latitude:T' END,
        CASE WHEN r."latitude" <> '' AND NOT regexp_full_match(r."latitude", '(?:[+-]?[0-9]+)|(?:[+-]?[0-9]*\.[0-9]+)|(?:[+-]?[0-9]*\.?[0-9]+[eE][+-]?[0-9]+)') AND try_cast(r."latitude" AS DOUBLE) IS NOT NULL THEN 'latitude:F' END,
        CASE WHEN coalesce(r."longitude", '') = '' THEN 'longitude:N' END,
        CASE WHEN r."longitude" <> '' AND try_cast(r."longitude" AS DOUBLE) IS NULL THEN 'longitude:T' END,
        CASE WHEN r."longitude" <> '' AND NOT regexp_full_match(r."longitude", '(?:[+-]?[0-9]+)|(?:[+-]?[0-9]*\.[0-9]+)|(?:[+-]?[0-9]*\.?[0-9]+[eE][+-]?[0-9]+)') AND try_cast(r."longitude" AS DOUBLE) IS NOT NULL THEN 'longitude:F' END,
        CASE WHEN coalesce(r."branch_opening_date", '') = '' THEN 'branch_opening_date:N' END,
        CASE WHEN r."branch_opening_date" <> '' AND try_cast(r."branch_opening_date" AS DATE) IS NULL THEN 'branch_opening_date:T' END,
        CASE WHEN r."branch_opening_date" <> '' AND NOT regexp_full_match(r."branch_opening_date", '(?:[0-9]{4}-[0-9]{2}-[0-9]{2})') AND try_cast(r."branch_opening_date" AS DATE) IS NOT NULL THEN 'branch_opening_date:F' END,
        CASE WHEN coalesce(r."branch_status", '') = '' THEN 'branch_status:N' END,
        CASE WHEN r."branch_status" <> '' AND r."branch_status" NOT IN ('Active', 'Temporarily Closed') THEN 'branch_status:V1' END
    ], x -> x IS NOT NULL) AS _dq_issues
    from {{ source('bronze_raw', 'branches') }} r
),
r as (
    select
        o.* REPLACE (
        CASE WHEN map_contains(c.m, 'branch_id') THEN c.m['branch_id'] ELSE o."branch_id" END AS "branch_id",
        CASE WHEN map_contains(c.m, 'branch_code') THEN c.m['branch_code'] ELSE o."branch_code" END AS "branch_code",
        CASE WHEN map_contains(c.m, 'branch_name') THEN c.m['branch_name'] ELSE o."branch_name" END AS "branch_name",
        CASE WHEN map_contains(c.m, 'branch_type') THEN c.m['branch_type'] ELSE o."branch_type" END AS "branch_type",
        CASE WHEN map_contains(c.m, 'address') THEN c.m['address'] ELSE o."address" END AS "address",
        CASE WHEN map_contains(c.m, 'city') THEN c.m['city'] ELSE o."city" END AS "city",
        CASE WHEN map_contains(c.m, 'state') THEN c.m['state'] ELSE o."state" END AS "state",
        CASE WHEN map_contains(c.m, 'country') THEN c.m['country'] ELSE o."country" END AS "country",
        CASE WHEN map_contains(c.m, 'postal_code') THEN c.m['postal_code'] ELSE o."postal_code" END AS "postal_code",
        CASE WHEN map_contains(c.m, 'geographic_zone') THEN c.m['geographic_zone'] ELSE o."geographic_zone" END AS "geographic_zone",
        CASE WHEN map_contains(c.m, 'phone') THEN c.m['phone'] ELSE o."phone" END AS "phone",
        CASE WHEN map_contains(c.m, 'email') THEN c.m['email'] ELSE o."email" END AS "email",
        CASE WHEN map_contains(c.m, 'opening_time') THEN c.m['opening_time'] ELSE o."opening_time" END AS "opening_time",
        CASE WHEN map_contains(c.m, 'closing_time') THEN c.m['closing_time'] ELSE o."closing_time" END AS "closing_time",
        CASE WHEN map_contains(c.m, 'has_atms') THEN c.m['has_atms'] ELSE o."has_atms" END AS "has_atms",
        CASE WHEN map_contains(c.m, 'atm_count') THEN c.m['atm_count'] ELSE o."atm_count" END AS "atm_count",
        CASE WHEN map_contains(c.m, 'has_teller_windows') THEN c.m['has_teller_windows'] ELSE o."has_teller_windows" END AS "has_teller_windows",
        CASE WHEN map_contains(c.m, 'teller_window_count') THEN c.m['teller_window_count'] ELSE o."teller_window_count" END AS "teller_window_count",
        CASE WHEN map_contains(c.m, 'latitude') THEN c.m['latitude'] ELSE o."latitude" END AS "latitude",
        CASE WHEN map_contains(c.m, 'longitude') THEN c.m['longitude'] ELSE o."longitude" END AS "longitude",
        CASE WHEN map_contains(c.m, 'branch_opening_date') THEN c.m['branch_opening_date'] ELSE o."branch_opening_date" END AS "branch_opening_date",
        CASE WHEN map_contains(c.m, 'branch_status') THEN c.m['branch_status'] ELSE o."branch_status" END AS "branch_status"
        ),
        coalesce(list_sort(map_keys(c.m)), []::VARCHAR[]) AS _corrected_columns
    from o
    left join c on c.source_file = o._source_file and c.record_no = o._record_no
)
select
    nullif(r."branch_id", '') AS "branch_id",
    nullif(r."branch_code", '') AS "branch_code",
    nullif(r."branch_name", '') AS "branch_name",
    nullif(r."branch_type", '') AS "branch_type",
    nullif(r."address", '') AS "address",
    nullif(r."city", '') AS "city",
    nullif(r."state", '') AS "state",
    nullif(r."country", '') AS "country",
    nullif(r."postal_code", '') AS "postal_code",
    nullif(r."geographic_zone", '') AS "geographic_zone",
    nullif(r."phone", '') AS "phone",
    nullif(r."email", '') AS "email",
    try_cast(nullif(r."opening_time", '') AS TIME) AS "opening_time",
    try_cast(nullif(r."closing_time", '') AS TIME) AS "closing_time",
    try_cast(nullif(r."has_atms", '') AS BOOLEAN) AS "has_atms",
    try_cast(nullif(r."atm_count", '') AS BIGINT) AS "atm_count",
    try_cast(nullif(r."has_teller_windows", '') AS BOOLEAN) AS "has_teller_windows",
    try_cast(nullif(r."teller_window_count", '') AS BIGINT) AS "teller_window_count",
    try_cast(nullif(r."latitude", '') AS DOUBLE) AS "latitude",
    try_cast(nullif(r."longitude", '') AS DOUBLE) AS "longitude",
    try_cast(nullif(r."branch_opening_date", '') AS DATE) AS "branch_opening_date",
    nullif(r."branch_status", '') AS "branch_status",
    cast(r._partition_date AS date) AS _partition_date,
    r._source_file,
    r._record_no,
    r._record_sha256,
    r._parse_status,
    '2dfb3f6d17d6' AS _contract_version,
    r._dq_issues,
    r._corrected_columns
from r
